const express = require('express');
const { NotificationChannel } = require('../models');
const { auth } = require('../auth');

const app = express();

app.get('/api/channels/:channelId/vapid-subject', auth, async (req, res) => {
  const { channelId } = req.params;

  // Filter query to verify organization ownership
  const channel = await NotificationChannel.findOne({
    where: {
      id: channelId,
      organizationId: req.user.organizationId
    }
  });

  if (!channel) {
    return res.status(404).json({ error: 'Channel not found in your organization' });
  }

  res.json({
    channelId: channel.id,
    subjectContact: channel.vapidContactSubject,
    operatorEmail: channel.emergencyContactEmail
  });
});

app.listen(8103);
